PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR

VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR

VAR
    low_limit : INT := 10;
    high_limit : INT := 90;
    pump_timer : TON;
END_VAR

pump_timer(IN := PumpIn, PT := T#1s);

IF Level <= low_limit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSIF Level >= high_limit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

IF Level >= high_limit AND pump_timer.Q THEN
    PumpIn := FALSE;
END_IF;

END_PROGRAM

