// Check if the level is within the safe operating range
IF Level >= high_limit THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSIF Level <= low_limit THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
ELSE
    PumpIn := FALSE;
