PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    LowLimit : INT := 10;
    HighLimit : INT := 90;
    LevelBelowLow : BOOL;
    LevelAboveHigh : BOOL;
END_VAR

// Check if level is below low limit
LevelBelowLow := Level <= LowLimit;

// Check if level is above high limit
LevelAboveHigh := Level >= HighLimit;

// Implement hysteresis logic for pump control
IF LevelAboveHigh THEN
    PumpIn := FALSE; // Turn off pump if level is above high limit
ELSIF LevelBelowLow THEN
    PumpIn := TRUE; // Turn on pump if level is below low limit
ELSE
    PumpIn := FALSE; // Keep pump off otherwise
END_IF;

// Ensure outlet valve opens when level is at or above high limit
ValveOut := LevelAboveHigh;

// Safety check: pump must not run while level is at or above high limit
IF LevelAboveHigh AND PumpIn THEN
    PumpIn := FALSE; // Override pump operation if safety condition violated
END_IF;
END_PROGRAM

