    PumpIn := FALSE;
ELSE
    // Hysteresis logic for PumpIn
    IF Level <= LowLimit THEN
        PumpIn := TRUE;
    ELSE
        PumpIn := FALSE;
    END_IF;

    // Logic for ValveOut
    IF Level >= HighLimit THEN
        ValveOut := TRUE;
    ELSE
        ValveOut := FALSE;
    END_IF;
END_IF;

// Ensure PumpTimer is not used if not needed
IF NOT PumpIn AND NOT ValveOut THEN
    PumpTimer(IN := FALSE);
ELSE
    PumpTimer(IN := PumpIn OR ValveOut, PT := T#1s); // Set timer preset as needed
END_IF;

