PROGRAM tank_level
VAR_INPUT
    Level : INT;
END_VAR
VAR_OUTPUT
    PumpIn : BOOL;
    ValveOut : BOOL;
END_VAR
VAR
    low_limit : INT := 10;
    high_limit : INT := 90;
    prev_level : INT := 0;
    pump_timer : TON;
END_VAR

// Initialize pump timer with a short delay
pump_timer(IN := TRUE, PT := T#1s);

IF Level <= low_limit AND NOT pump_timer.Q THEN
    PumpIn := TRUE;
    ValveOut := FALSE;
    prev_level := Level;
ELSIF Level >= high_limit OR (prev_level > high_limit AND NOT pump_timer.Q) THEN
    PumpIn := FALSE;
    ValveOut := TRUE;
ELSE
    PumpIn := FALSE;
    ValveOut := FALSE;
END_IF;

// Reset pump timer if level changes direction
IF Level <> prev_level THEN
    pump_timer(IN := FALSE);
    pump_timer(IN := TRUE);
END_IF;

END_PROGRAM

