PROGRAM airlock
VAR_INPUT
    OpenA_Cmd : BOOL;
    OpenB_Cmd : BOOL;
END_VAR
VAR_OUTPUT
    DoorA : BOOL;
    DoorB : BOOL;
END_VAR
VAR
    DoorA_TON : TON;
    DoorB_TON : TON;
END_VAR

DoorA := FALSE;
DoorB := FALSE;

IF OpenA_Cmd THEN
    IF NOT OpenB_Cmd THEN
        DoorA := TRUE;
        DoorB_TON(IN := TRUE, PT := T#0s);
    ELSE
        DoorA := FALSE;
        DoorA_TON(IN := FALSE, PT := T#0s);
    END_IF;
ELSIF OpenB_Cmd THEN
    IF NOT OpenA_Cmd THEN
        DoorB := TRUE;
        DoorA_TON(IN := TRUE, PT := T#0s);
    ELSE
        DoorB := FALSE;
        DoorB_TON(IN := FALSE, PT := T#0s);
    END_IF;
ELSE
    DoorA := FALSE;
    DoorB := FALSE;
    DoorA_TON(IN := FALSE, PT := T#0s);
    DoorB_TON(IN := FALSE, PT := T#0s);
END_IF;

END_PROGRAM

