PROGRAM conveyor_ctrl
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    GuardClosed : BOOL;
    Fault : BOOL;
END_VAR

VAR_OUTPUT
    Conveyor : BOOL;
END_VAR

VAR
    Running : BOOL := FALSE;
    StartTimer : TON;
    StopTimer : TON;
END_VAR

StartTimer(IN := StartPB AND GuardClosed AND NOT Fault AND NOT Running, PT := T#0s);
StopTimer(IN := StopPB OR NOT GuardClosed OR Fault, PT := T#0s);

Running := Running OR StartTimer.Q;

Conveyor := Running AND NOT StopTimer.Q;
END_PROGRAM

