PROGRAM intersection
VAR
    NS_G : BOOL;
    NS_Y : BOOL;
    NS_R : BOOL;
    EW_G : BOOL;
    EW_Y : BOOL;
    EW_R : BOOL;
    State : INT := 0;
    NS_GreenTimer : TON;
    NS_YellowTimer : TON;
    NS_AllRedTimer : TON;
    EW_GreenTimer : TON;
    EW_YellowTimer : TON;
    EW_AllRedTimer : TON;
END_VAR

NS_GreenTimer(IN := (State = 0 OR State = 3), PT := T#2s);
NS_YellowTimer(IN := (State = 1 OR State = 4), PT := T#1s);
NS_AllRedTimer(IN := (State = 2 OR State = 5), PT := T#1s);

EW_GreenTimer(IN := (State = 3 OR State = 0), PT := T#2s);
EW_YellowTimer(IN := (State = 4 OR State = 1), PT := T#1s);
EW_AllRedTimer(IN := (State = 5 OR State = 2), PT := T#1s);

NS_G := NS_GreenTimer.Q AND NOT (EW_G OR EW_Y);
NS_Y := NS_YellowTimer.Q AND NOT (EW_G OR EW_Y);
NS_R := NS_AllRedTimer.Q;

EW_G := EW_GreenTimer.Q AND NOT (NS_G OR NS_Y);
EW_Y := EW_YellowTimer.Q AND NOT (NS_G OR NS_Y);
EW_R := EW_AllRedTimer.Q;

CASE State OF
    0: 
        IF NS_GreenTimer.Q THEN
            State := 1;
        END_IF;
    1: 
        IF NS_YellowTimer.Q THEN
            State := 2;
        END_IF;
    2: 
        IF NS_AllRedTimer.Q THEN
            State := 3;
        END_IF;
    3: 
        IF EW_GreenTimer.Q THEN
            State := 4;
        END_IF;
    4: 
        IF EW_YellowTimer.Q THEN
            State := 5;
        END_IF;
    5: 
        IF EW_AllRedTimer.Q THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM intersection
VAR
    State : INT;
    NS_G, NS_Y, NS_R, EW_G, EW_Y, EW_R : BOOL;
    NS_G_TON, NS_Y_TON, NS_R_TON : TON;
    EW_G_TON, EW_Y_TON, EW_R_TON : TON;
    PT_GREEN : TIME := T#2s;
    PT_YELLOW : TIME := T#1s;
    PT_ALLRED : TIME := T#1s;
END_VAR

State := State + 1;

CASE State OF
    0:
        NS_G := TRUE;
        NS_Y := FALSE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        NS_G_TON(IN := NS_G, PT := PT_GREEN);
        NS_Y_TON(IN := NS_Y, PT := PT_YELLOW);
        NS_R_TON(IN := NS_R, PT := PT_ALLRED);
        EW_G_TON(IN := FALSE, PT := T#0s);
        EW_Y_TON(IN := FALSE, PT := T#0s);
        EW_R_TON(IN := TRUE, PT := PT_ALLRED);

    1:
        NS_G := FALSE;
        NS_Y := TRUE;
        NS_R := FALSE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        NS_G_TON(IN := NS_G, PT := PT_GREEN);
        NS_Y_TON(IN := NS_Y, PT := PT_YELLOW);
        NS_R_TON(IN := NS_R, PT := PT_ALLRED);
        EW_G_TON(IN := FALSE, PT := T#0s);
        EW_Y_TON(IN := FALSE, PT := T#0s);
        EW_R_TON(IN := TRUE, PT := PT_ALLRED);

    2:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        NS_G_TON(IN := FALSE, PT := T#0s);
        NS_Y_TON(IN := FALSE, PT := T#0s);
        NS_R_TON(IN := TRUE, PT := PT_ALLRED);
        EW_G_TON(IN := FALSE, PT := T#0s);
        EW_Y_TON(IN := FALSE, PT := T#0s);
        EW_R_TON(IN := TRUE, PT := PT_ALLRED);

    3:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := TRUE;
        EW_Y := FALSE;
        EW_R := FALSE;
        NS_G_TON(IN := FALSE, PT := T#0s);
        NS_Y_TON(IN := FALSE, PT := T#0s);
        NS_R_TON(IN := TRUE, PT := PT_ALLRED);
        EW_G_TON(IN := EW_G, PT := PT_GREEN);
        EW_Y_TON(IN := EW_Y, PT := PT_YELLOW);
        EW_R_TON(IN := EW_R, PT := PT_ALLRED);

    4:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := TRUE;
        EW_R := FALSE;
        NS_G_TON(IN := FALSE, PT := T#0s);
        NS_Y_TON(IN := FALSE, PT := T#0s);
        NS_R_TON(IN := TRUE, PT := PT_ALLRED);
        EW_G_TON(IN := EW_G, PT := PT_GREEN);
        EW_Y_TON(IN := EW_Y, PT := PT_YELLOW);
        EW_R_TON(IN := EW_R, PT := PT_ALLRED);

    5:
        NS_G := FALSE;
        NS_Y := FALSE;
        NS_R := TRUE;
        EW_G := FALSE;
        EW_Y := FALSE;
        EW_R := TRUE;
        NS_G_TON(IN := FALSE, PT := T#0s);
        NS_Y_TON(IN := FALSE, PT := T#0s);
        NS_R_TON(IN := TRUE, PT := PT_ALLRED);
        EW_G_TON(IN := FALSE, PT := T#0s);
        EW_Y_TON(IN := FALSE, PT := T#0s);
        EW_R_TON(IN := TRUE, PT := PT_ALLRED);
END_CASE;

NS_G := NS_G_TON.Q;
NS_Y := NS_Y_TON.Q;
NS_R := NS_R_TON.Q;
EW_G := EW_G_TON.Q;
EW_Y := EW_Y_TON.Q;
EW_R := EW_R_TON.Q;

IF State > 5 THEN
    State := 0;
END_IF;
END_PROGRAM

