    END_IF;

    IF NOT (Heater OR Agitator) OR Level < LIQ_MIN THEN
        Heater := FALSE;
        Agitator := FALSE;
    END_IF;
END_IF;

END_PROGRAM

PROGRAM batch_reactor
VAR
    State : INT := 0;
    FillValve : BOOL := FALSE;
    Heater : BOOL := FALSE;
    Agitator : BOOL := FALSE;
    DrainValve : BOOL := FALSE;
    LIQ_MIN : INT := 10;
    LVL_HIGH : INT := 80;
    LVL_LOW : INT := 5;
    TEMP_SET : INT := 100;
    PT_REACT : TIME := T#3s;
    LIQ_LEVEL_OK : BOOL;
    FILL_TIMER : TON;
    DRAIN_TIMER : TON;
END_VAR

// Update Liquid Level OK flag
LIQ_LEVEL_OK := (Level >= LIQ_MIN);

// Check if Emergency Stop is active
IF NOT EStop THEN
    State := 0;
    FillValve := FALSE;
    Heater := FALSE;
    Agitator := FALSE;
    DrainValve := FALSE;
    FILL_TIMER(IN := FALSE);
    DRAIN_TIMER(IN := FALSE);
END_IF;

CASE State OF
    0: // Idle
        IF StartBatch AND EStop THEN
            State := 1;
            FILL_TIMER(IN := TRUE, PT := T#1s); // Start fill timer
        END_IF;

    1: // Fill
        IF FILL_TIMER.Q THEN
            FillValve := TRUE;
            IF Level >= LVL_HIGH THEN
                FillValve := FALSE;
                State := 2;
            END_IF;
        END_IF;

    2: // Heat
        IF LIQ_LEVEL_OK THEN
            Heater := TRUE;
            Agitator := TRUE;
            IF Temp >= TEMP_SET THEN
                State := 3;
                DRAIN_TIMER(IN := TRUE, PT := PT_REACT); // Start react timer
            END_IF;
        ELSE
            Heater := FALSE;
            Agitator := FALSE;
        END_IF;

    3: // React
        IF DRAIN_TIMER.Q THEN
            State := 4;
        END_IF;

    4: // Drain
        IF LIQ_LEVEL_OK THEN
            DrainValve := TRUE;
            IF Level <= LVL_LOW THEN
                DrainValve := FALSE;
                State := 0;
            END_IF;
        ELSE
            DrainValve := FALSE;
        END_IF;
END_CASE;

// Safety Conditions
IF FillValve AND DrainValve THEN
    FillValve := FALSE;
    DrainValve := FALSE;
END_IF;

IF Heater AND NOT LIQ_LEVEL_OK THEN
    Heater := FALSE;
    Agitator := FALSE;
END_IF;
END_PROGRAM

