            IF Level >= 90 THEN
                State := 2;
                Pump := FALSE;
                Valve := TRUE;
            END_IF;

        2: -- Draining
            IF Level <= 10 THEN
                State := 0;
                Pump := FALSE;
                Valve := FALSE;
            END_IF;
    END_CASE;
END_IF;

-- Safety conditions
IF Pump AND Valve THEN
    Pump := FALSE;
    Valve := FALSE;
END_IF;

IF Level >= 90 THEN
    Pump := FALSE;
END_IF;

IF Level <= 10 THEN
    Valve := FALSE;
END_IF;

