    Actuator : BOOL;
END_VAR

VAR
    Armed : BOOL := FALSE;
    Previous_LH : BOOL := FALSE;
    Previous_RH : BOOL := FALSE;
    Button_Released_Together : BOOL := TRUE;
END_VAR

// Check if both buttons are pressed
IF LH AND RH THEN
    // If the buttons were not pressed previously, it means they were just pressed
    IF NOT Previous_LH OR NOT Previous_RH THEN
        Button_Released_Together := FALSE;
    END_IF;

    // Update the previous state of the buttons
    Previous_LH := LH;
    Previous_RH := RH;

    // Check if the control should be armed
    IF Button_Released_Together THEN
        Armed := TRUE;
    END_IF;

    // Set the actuator to run
    Actuator := TRUE;
ELSE
    // Reset the actuator if either button is not pressed
    Actuator := FALSE;

    // Check if both buttons were released together
    IF NOT LH AND NOT RH THEN
        Button_Released_Together := TRUE;
    ELSE
        Button_Released_Together := FALSE;
    END_IF;

    // Disarm the control if exactly one button is pressed
    IF (LH XOR RH) THEN
        Armed := FALSE;
    END_IF;
END_IF;

// Ensure the actuator cannot run if the control is not armed
IF NOT Armed THEN
    Actuator := FALSE;
END_IF;
END_PROGRAM

