    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    PumpTimer : TON;
END_VAR

PumpTimer(IN := NOT(EStop) AND Demand, PT := T#1s);

PrevDemand := Demand;

IF NOT(EStop) THEN
    IF Demand THEN
        CASE Lead OF
            0: 
                Pump1 := TRUE;
                Pump2 := FALSE;
            1: 
                Pump1 := FALSE;
                Pump2 := TRUE;
        END_CASE;
        Lead := 1 - Lead; // Alternate lead
    ELSE
        Pump1 := FALSE;
        Pump2 := FALSE;
    END_IF;
ELSE
    Pump1 := FALSE;
    Pump2 := FALSE;
END_IF;

