END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    TmpPump1 : BOOL := FALSE;
    TmpPump2 : BOOL := FALSE;
END_VAR

// Detect falling edge of Demand
PrevDemand := Demand;

IF NOT EStop THEN
    // Both pumps off if EStop is activated
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    IF Demand AND NOT PrevDemand THEN
        // Demand has started, switch lead pump
        Lead := 1 - Lead;
    END_IF;

    IF Demand THEN
        // Only one pump should run when Demand is high
        IF Lead = 0 THEN
            TmpPump1 := TRUE;
            TmpPump2 := FALSE;
        ELSE
            TmpPump1 := FALSE;
            TmpPump2 := TRUE;
        END_IF;
    ELSE
        // Turn off both pumps if Demand ends
        TmpPump1 := FALSE;
        TmpPump2 := FALSE;
    END_IF;
END_IF;

// Assign output values
Pump1 := TmpPump1;
Pump2 := TmpPump2;
