PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    TmpPump1 : BOOL := FALSE;
    TmpPump2 : BOOL := FALSE;
END_VAR

// Detect falling edge of Demand
PrevDemand := Demand;

// Check for emergency stop
IF NOT EStop THEN
    Pump1 := FALSE;
    Pump2 := FALSE;
    Lead := 0;
    PrevDemand := FALSE;
ELSE
    // Alternate lead if demand ends
    IF NOT Demand AND PrevDemand THEN
        Lead := 1 - Lead;
    END_IF;

    // Determine which pump should run
    IF Demand THEN
        CASE Lead OF
            0 :
                TmpPump1 := TRUE;
                TmpPump2 := FALSE;
            1 :
                TmpPump1 := FALSE;
                TmpPump2 := TRUE;
        END_CASE;
    ELSE
        TmpPump1 := FALSE;
        TmpPump2 := FALSE;
    END_IF;

    // Ensure only one pump runs at a time
    Pump1 := TmpPump1 AND NOT TmpPump2;
    Pump2 := TmpPump2 AND NOT TmpPump1;
END_IF;

END_PROGRAM

