PumpTimer(IN := NOT EStop AND Demand, PT := T#1s);

IF NOT EStop THEN
    IF Demand THEN
        IF NOT PrevDemand THEN
            Lead := 1 - Lead;
        END_IF
        Pump1 := (Lead = 0);
        Pump2 := (Lead = 1);
    ELSE
        Pump1 := FALSE;
