PROGRAM pump_alt
VAR_INPUT
    Demand : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    Pump1 : BOOL;
    Pump2 : BOOL;
END_VAR

VAR
    Lead : INT := 0;
    PrevDemand : BOOL := FALSE;
    DemandTimer : TON;
END_VAR

Pump1 := FALSE;
Pump2 := FALSE;

IF NOT EStop THEN
    // Emergency stop activated, stop both pumps
    Pump1 := FALSE;
    Pump2 := FALSE;
ELSE
    DemandTimer(IN := Demand AND NOT PrevDemand, PT := T#1s);

    IF DemandTimer.Q THEN
        Lead := 1 - Lead; // Toggle lead pump
        DemandTimer(IN := FALSE, PT := T#1s); // Reset timer
    END_IF

    CASE Lead OF
        0:
            Pump1 := Demand;
            Pump2 := FALSE;
        1:
            Pump1 := FALSE;
            Pump2 := Demand;
    END_CASE
END_IF

PrevDemand := Demand;
END_PROGRAM

