VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR

VAR
    State : INT := 0;
    OpenTimer : TON;
    CloseTimer : TON;
END_VAR

CASE State OF
    0:  // Idle
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
        END_IF;

    1:  // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        IF OpenLimit OR Obstruction THEN
            MotorOpen := FALSE;
            State := 0;
        END_IF;

    2:  // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        IF CloseLimit OR Obstruction THEN
            MotorClose := FALSE;
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM gate
VAR_INPUT
    OpenCmd : BOOL;
    CloseCmd : BOOL;
    OpenLimit : BOOL;
    CloseLimit : BOOL;
    Obstruction : BOOL;
END_VAR

VAR_OUTPUT
    MotorOpen : BOOL;
    MotorClose : BOOL;
END_VAR

VAR
    State : INT := 0;
    OpeningTimer : TON;
    ClosingTimer : TON;
END_VAR

CASE State OF
    0: // Idle
        MotorOpen := FALSE;
        MotorClose := FALSE;
        IF OpenCmd AND NOT OpenLimit THEN
            State := 1;
        ELSIF CloseCmd AND NOT (CloseLimit OR Obstruction) THEN
            State := 2;
        END_IF;

    1: // Opening
        MotorOpen := TRUE;
        MotorClose := FALSE;
        OpeningTimer(IN := TRUE, PT := T#5s);
        IF OpenLimit OR OpeningTimer.Q THEN
            State := 0;
        END_IF;

    2: // Closing
        MotorOpen := FALSE;
        MotorClose := TRUE;
        ClosingTimer(IN := TRUE, PT := T#5s);
        IF CloseLimit OR Obstruction OR ClosingTimer.Q THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    Timer_C3 : TON;
    Timer_C2 : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

IF NOT EStop THEN
    CASE State OF
        0:
            IF StartPB THEN
                State := 1;
                Timer_C3(IN := TRUE, PT := PT_SEQ);
            END_IF;
        1:
            IF Timer_C3.Q AND NOT StopPB THEN
                State := 2;
                Timer_C2(IN := TRUE, PT := PT_SEQ);
            END_IF;
        2:
            IF Timer_C2.Q AND NOT StopPB THEN
                State := 3;
            END_IF;
        3:
            IF StopPB OR NOT Timer_C2.Q THEN
                State := 0;
                Timer_C3(IN := FALSE);
                Timer_C2(IN := FALSE);
            END_IF;
    END_CASE;

    C1 := (State >= 3);
    C2 := (State >= 2);
    C3 := (State >= 1);
ELSE
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    Timer_C3(IN := FALSE);
    Timer_C2(IN := FALSE);
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
    State : INT;
    T1 : TON;
    T2 : TON;
END_VAR

IF StopPB OR NOT EStop THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    T1(IN := FALSE);
    T2(IN := FALSE);
ELSIF StartPB AND NOT EStop THEN
    CASE State OF
        0:
            State := 1;
            C3 := TRUE;
            C2 := FALSE;
            C1 := FALSE;
            T1(IN := TRUE, PT := T#2s);
        1:
            IF T1.Q THEN
                State := 2;
                C3 := TRUE;
                C2 := TRUE;
                C1 := FALSE;
                T2(IN := TRUE, PT := T#2s);
            END_IF;
        2:
            IF T2.Q THEN
                State := 3;
                C3 := TRUE;
                C2 := TRUE;
                C1 := TRUE;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    T1 : TON;
    T2 : TON;
END_VAR

T1(IN := (State = 2) AND NOT EStop, PT := T#2s);
T2(IN := (State >= 1) AND NOT EStop, PT := T#2s);

IF StopPB OR NOT EStop THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
ELSIF StartPB AND NOT EStop THEN
    CASE State OF
        0: 
            State := 1;
            C3 := TRUE;
        1: 
            IF T1.Q THEN
                State := 2;
                C2 := TRUE;
            END_IF;
        2: 
            IF T2.Q THEN
                State := 3;
                C1 := TRUE;
                C2 := TRUE;
                C3 := TRUE;
            END_IF;
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
    State : INT := 0;
    TON_C3 : TON;
    TON_C2 : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

TON_C3(IN := NOT EStop AND (State >= 1), PT := PT_SEQ);
TON_C2(IN := NOT EStop AND (State >= 2), PT := PT_SEQ);

IF StartPB AND NOT EStop THEN
    CASE State OF
        0:
            IF TON_C3.Q THEN
                State := 1;
            END_IF;
        1:
            IF TON_C2.Q THEN
                State := 2;
            END_IF;
        2:
            IF TON_C2.Q THEN
                State := 3;
            END_IF;
        3:
            State := 3;
    END_CASE;
ELSIF StopPB OR NOT EStop THEN
    State := 0;
END_IF;

C1 := (State = 3) AND TON_C2.Q;
C2 := (State >= 2) AND TON_C2.Q;
C3 := (State >= 1) AND TON_C3.Q;
END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    T1 : TON;
    T2 : TON;
END_VAR

VAR_CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

T1(IN := StartPB AND NOT EStop, PT := PT_SEQ);
T2(IN := T1.Q AND NOT EStop, PT := PT_SEQ);

CASE State OF
    0 :
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1 :
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2 :
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3 :
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
    T1(IN := FALSE);
    T2(IN := FALSE);
END_IF;

IF T1.Q AND NOT T2.Q THEN
    State := 1;
ELSIF T2.Q THEN
    State := 2;
END_IF;

IF NOT EStop THEN
    State := 3;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    T1 : TON;
    T2 : TON;
END_VAR

VAR_CONSTANT
    PT_SEQ : TIME := T#2s;
END_VAR

IF EStop THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    T1(IN := FALSE);
    T2(IN := FALSE);
ELSIF StartPB AND NOT StopPB THEN
    CASE State OF
        0:
            C1 := FALSE;
            C2 := FALSE;
            C3 := TRUE;
            T1(IN := TRUE, PT := PT_SEQ);
            State := 1;
        1:
            IF T1.Q THEN
                C1 := FALSE;
                C2 := TRUE;
                C3 := TRUE;
                T2(IN := TRUE, PT := PT_SEQ);
                State := 2;
            END_IF;
        2:
            IF T2.Q THEN
                C1 := TRUE;
                C2 := TRUE;
                C3 := TRUE;
                State := 3;
            END_IF;
        3:
            C1 := TRUE;
            C2 := TRUE;
            C3 := TRUE;
    END_CASE;
ELSE
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    T1(IN := FALSE);
    T2(IN := FALSE);
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    TON_C3 : TON;
    TON_C2 : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

TON_C3(IN := StartPB AND NOT EStop AND State = 0, PT := PT_SEQ);
TON_C2(IN := TON_C3.Q AND NOT EStop AND State <= 1, PT := PT_SEQ);

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TON_C3.Q;
    2:
        C1 := FALSE;
        C2 := TON_C2.Q;
        C3 := TON_C3.Q;
    3:
        C1 := TON_C2.Q;
        C2 := TON_C2.Q;
        C3 := TON_C3.Q;
    ELSE:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
END_IF;

IF TON_C3.Q AND TON_C2.Q THEN
    State := 3;
ELSIF TON_C3.Q THEN
    State := 2;
ELSIF TON_C2.Q THEN
    State := 1;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    TON_C3 : TON;
    TON_C2 : TON;
    PT_SEQ : TIME := T#2s;
END_VAR

TON_C3(IN := NOT EStop AND StartPB, PT := PT_SEQ);
TON_C2(IN := NOT EStop AND TON_C3.Q, PT := PT_SEQ);

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
        IF TON_C3.Q THEN
            State := 1;
        END_IF;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
        IF TON_C2.Q THEN
            State := 2;
        END_IF;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
        IF StopPB OR EStop THEN
            State := 0;
        END_IF;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
        IF StopPB OR EStop THEN
            State := 0;
        END_IF;
END_CASE;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    PT_SEQ : TIME := T#2s;
    T_C3 : TON;
    T_C2 : TON;
END_VAR

IF EStop THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    T_C3(IN := FALSE);
    T_C2(IN := FALSE);
ELSIF StopPB THEN
    State := 0;
    C1 := FALSE;
    C2 := FALSE;
    C3 := FALSE;
    T_C3(IN := FALSE);
    T_C2(IN := FALSE);
ELSIF StartPB AND NOT EStop AND NOT StopPB THEN
    CASE State OF
        0:
            State := 1;
            C1 := FALSE;
            C2 := FALSE;
            C3 := TRUE;
            T_C3(IN := TRUE, PT := PT_SEQ);
        1:
            IF T_C3.Q THEN
                State := 2;
                C1 := FALSE;
                C2 := TRUE;
                C3 := TRUE;
                T_C3(IN := FALSE);
                T_C2(IN := TRUE, PT := PT_SEQ);
            END_IF;
        2:
            IF T_C2.Q THEN
                State := 3;
                C1 := TRUE;
                C2 := TRUE;
                C3 := TRUE;
                T_C2(IN := FALSE);
            END_IF;
        3:
            // Already running all three, do nothing
    END_CASE;
END_IF;

END_PROGRAM

PROGRAM conveyor3
VAR_INPUT
    StartPB : BOOL;
    StopPB : BOOL;
    EStop : BOOL;
END_VAR

VAR_OUTPUT
    C1 : BOOL;
    C2 : BOOL;
    C3 : BOOL;
END_VAR

VAR
    State : INT := 0;
    PT_SEQ : TIME := T#2s;
    T_C3 : TON;
    T_C2 : TON;
END_VAR

T_C3(IN := NOT EStop AND StartPB AND (State = 0 OR State = 1), PT := PT_SEQ);
T_C2(IN := NOT EStop AND T_C3.Q AND (State = 0 OR State = 1 OR State = 2), PT := PT_SEQ);

CASE State OF
    0:
        C1 := FALSE;
        C2 := FALSE;
        C3 := FALSE;
    1:
        C1 := FALSE;
        C2 := FALSE;
        C3 := TRUE;
    2:
        C1 := FALSE;
        C2 := TRUE;
        C3 := TRUE;
    3:
        C1 := TRUE;
        C2 := TRUE;
        C3 := TRUE;
END_CASE;

IF StopPB OR NOT EStop THEN
    State := 0;
    T_C3(IN := FALSE);
    T_C2(IN := FALSE);
END_IF;

IF T_C3.Q AND NOT T_C2.Q THEN
    State := 1;
ELSIF T_C2.Q AND T_C3.Q THEN
    IF T_C3.Q AND NOT T_C2.Q THEN
        State := 2;
    ELSE
        State := 3;
    END_IF;
END_IF;
END_PROGRAM

PROGRAM dosing
VAR_INPUT
    Trigger : BOOL;
    Reset : BOOL;
END_VAR

VAR_OUTPUT
    Done : BOOL;
    Count : INT := 0;
END_VAR

VAR
    PrevTrigger : BOOL := FALSE;
    T1 : TON;
END_VAR

T1(IN := Trigger AND NOT PrevTrigger, PT := T#1ms);

IF Reset THEN
    Count := 0;
    Done := FALSE;
ELSIF T1.Q THEN
    IF Count < 3 THEN
        Count := Count + 1;
    END_IF;
    IF Count >= 3 THEN
        Done := TRUE;
    ELSE
        Done := FALSE;
    END_IF;
END_IF;

PrevTrigger := Trigger;

END_PROGRAM

